import * as sfx from './sfx.js?v=2026-11-21-e';
import { $, esc, toast, vibrate, fmtTime } from './ui.js?v=2026-11-21-e';
import { gameRenderers } from './games/index.js?v=2026-11-21-e';
import { THEMES, THEME_VARS } from './themes.js?v=2026-11-21-e';

const SESSION_KEY = 'nfcd:session';
const NICK_KEY = 'nfcd:nick';
const BRAND_URL = '/';
const SHOW_QR = true;
const LOGO = '/oyun/img/logo.png';
const ICON = '/oyun/img/logo-icon.png';
const OKUT = 'data:image/png;base64,';
const params = new URLSearchParams(location.search);

const state = {
  catalog: { games: [], categories: [] },
  room: null,      // sunucudan gelen oda durumu
  me: null,        // benim playerId'm
  game: null,      // { gameId, view }  -> bana özel oyun görünümü
  clockOffset: 0,  // sunucu saati - telefon saati
  category: 'hepsi',
  source: params.get('kaynak'), // QR hangi işletmeden okutuldu (istatistik)
  prefillCode: (params.get('oda') || '').toUpperCase().slice(0, 4),
  ended: null,
  busy: false,
};

const storage = {
  get(k) { try { return JSON.parse(localStorage.getItem(k)); } catch { return null; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch { /* gizli sekme */ } },
  del(k) { try { localStorage.removeItem(k); } catch { /* yok say */ } },
};

/* ======================= Socket ======================= */

// Sayfa Netlify'da, oyun sunucusu Render'da: bağlantı config.js'teki adrese gider.
const socket = io(window.OYUN_SUNUCU, { transports: ['websocket', 'polling'] });

function emit(event, payload = {}) {
  return new Promise((resolve) => {
    socket.timeout(8000).emit(event, payload, (err, res) =>
      resolve(err ? { ok: false, error: 'Sunucuya ulaşılamadı, tekrar dene.' } : res));
  });
}

/* ======================= Uzaktan hata kaydı ======================= */
// Oyun sırasında cihazda oluşan hatalar oyun sunucusuna bildirilir (sunucu bellekte son 200'ü tutar,
// /hatalar adresinden görülür). Kişisel veri yok: hata metni, oyun adı, tarayıcı/cihaz ve ekran ölçüsü.
const errSeen = new Set();
let errCount = 0;
function reportErr(tur, mesaj, yer) {
  try {
    const key = `${tur}|${mesaj}|${String(yer).slice(0, 120)}`;
    if (errSeen.has(key) || errCount >= 25) return;
    errSeen.add(key);
    errCount += 1;
    const ekran = `${screen.width}x${screen.height}@${(window.devicePixelRatio || 1).toFixed(2)}`;
    socket.emit('client:error', {
      tur, oyun: state.room?.gameId || '', mesaj: String(mesaj || '').slice(0, 500), yer: String(yer || '').slice(0, 700),
      cihaz: `${navigator.userAgent.slice(0, 220)} | ${ekran} | ${window.__gpu || '-'}`,
    });
  } catch { /* yok say */ }
}
window.addEventListener('error', (e) => reportErr('hata', e.message, `${e.filename || ''}:${e.lineno || 0}:${e.colno || 0} ${e.error?.stack || ''}`));
window.addEventListener('unhandledrejection', (e) => reportErr('söz', e.reason?.message || String(e.reason), e.reason?.stack || ''));
// oyunlar kendi hatalarını "[kurye] …" biçiminde konsola yazar: bunları da bildir
['error', 'warn'].forEach((lvl) => {
  const orig = console[lvl].bind(console);
  console[lvl] = (...a) => {
    orig(...a);
    if (typeof a[0] !== 'string' || !a[0].startsWith('[')) return;
    const ex = a.find((x) => x instanceof Error);
    const txt = a.map((x) => (x instanceof Error ? `${x.name}: ${x.message}` : typeof x === 'string' ? x : (() => { try { return JSON.stringify(x).slice(0, 200); } catch { return String(x); } })())).join(' ');
    reportErr(lvl === 'error' ? 'oyun-hatası' : 'oyun-uyarısı', txt, ex?.stack || '');
  };
});

const serverNow = () => Date.now() + state.clockOffset;
const isHost = () => !!state.room && state.room.hostId === state.me;
const hostName = () => state.room?.players.find((p) => p.isHost)?.nickname ?? 'oda sahibi';
const gameMeta = (id) => state.catalog.games.find((g) => g.id === id);
const inviteUrl = () => `${location.origin}/oyun/?oda=${state.room.code}`;

socket.on('connect', async () => {
  const saved = storage.get(SESSION_KEY);
  if (!saved?.code || !saved?.token) return render();

  const res = await emit('room:resume', saved);
  if (res.ok && !res.ended) {
    state.me = res.playerId;
    applyRoom(res.room);
    sendSeen();
  } else if (!res.ok) {
    storage.del(SESSION_KEY);
    state.room = null;
    render();
  }
});

socket.on('disconnect', () => { if (state.room) toast('Bağlantı koptu, tekrar bağlanıyor…'); });

// ---- İstatistik: sayfa açılışı işletme (QR kodu) bazında sayılır. Kişisel veri yok, yalnız sayaç. ----
// gunluk: bu cihaz bu işletmeye bugün ilk kez geldi · yeni: bu cihaz bu işletmenin QR'ını ilk kez okuttu
let ziyaretGitti = false;
socket.on('connect', () => {
  if (ziyaretGitti) return;
  ziyaretGitti = true;
  const kaynak = String(state.source || '').toLowerCase().slice(0, 40), k = kaynak || 'direkt';
  let yeni = false, gunluk = true;
  try {
    const bugun = new Date(Date.now() + 3 * 3600e3).toISOString().slice(0, 10);
    const z = JSON.parse(localStorage.getItem('nfcd:ziyaret') || 'null') || {};
    if (!z || typeof z !== 'object' || Array.isArray(z)) throw 0;
    yeni = !(k in z); gunluk = z[k] !== bugun; z[k] = bugun;
    const anahtarlar = Object.keys(z); if (anahtarlar.length > 60) delete z[anahtarlar[0]];
    localStorage.setItem('nfcd:ziyaret', JSON.stringify(z));
  } catch { try { localStorage.setItem('nfcd:ziyaret', '{}'); } catch { /* gizli sekme */ } }
  emit('stat:ziyaret', { source: kaynak, yeni, gunluk });
});
socket.on('catalog', (catalog) => {
  state.catalog = catalog;
  if (currentScreen === 'lobby') renderLobby();
  if (currentScreen === 'home') renderHome();
});
socket.on('room:state', applyRoom);
socket.on('game:state', (g) => {
  const prev = state.game && state.game.gameId === g.gameId ? state.game.view : null;
  state.game = g;
  sfx.onGameView(g.gameId, prev, g.view);
  if (currentScreen?.startsWith('game:')) updateGame();
});
socket.on('room:kicked', (payload) => {
  resetToHome();
  toast(payload?.message ?? 'Odadan çıkarıldın.');
});

socket.on('session:ended', (payload) => {
  state.ended = payload;
  storage.del(SESSION_KEY);
  closeSheet();
  vibrate([200, 100, 200]);
  renderOverlay();
});
socket.on('toast', (t) => toast(t.text));

function applyRoom(room) {
  if (!room) return;
  state.clockOffset = room.serverNow - Date.now();
  if (state.game && state.game.gameId !== room.gameId) state.game = null;
  const online = (r) => r?.players?.filter((p) => p.connected).length ?? 0;
  if (state.room && state.room.code === room.code && online(room) > online(state.room)) sfx.play('pop');
  state.room = room;
  render();
}

/* ======================= Ekran yönlendirme ======================= */

let currentScreen = null;

// ---- İşletme teması: sadece QR ile gelenlere (ya da o QR'ın odasındakilere) uygulanır ----
const SLUG_TAKMA = { 'eliz-cups-bowl': 'eliz' }; // QR'da görünen uzun ad -> tema kodu
const qrSlug = ((x) => SLUG_TAKMA[x] || x)(String(new URLSearchParams(location.search).get('kaynak') ?? window.OYUN_KAYNAK ?? '').toLowerCase()); // OYUN_KAYNAK: sadece önizleme sayfası kullanır
// Tema yalnızca bu açılışta ?kaynak=<kod> varsa geçerli olur; kodsuz açılan sayfa her zaman standart görünümdür.
const SLUG_OK = (x) => /^[a-z0-9](?:[a-z0-9-]{0,38}[a-z0-9])?$/.test(x);
// Panelden eklenen temalar sonradan yüklenir; kod geçerliyse şimdiden saklanır, tema gelince uygulanır
try { if (THEMES[qrSlug] || SLUG_OK(qrSlug)) sessionStorage.setItem('oyun-tema', qrSlug); else sessionStorage.removeItem('oyun-tema'); } catch { /* gizli sekme */ }
let themeSlug = null;
function currentThemeSlug() {
  let saved = ''; try { saved = sessionStorage.getItem('oyun-tema') ?? ''; } catch { /* yok say */ }
  if (saved && !THEMES[saved] && SLUG_OK(saved)) uzakTema(saved);
  const slug = THEMES[saved] ? saved : String(state.room?.source ?? '').toLowerCase();
  if (!THEMES[slug] && SLUG_OK(slug)) uzakTema(slug);
  return THEMES[slug] ? slug : null;
}
function syncTheme() {
  const slug = currentThemeSlug();
  if (slug === themeSlug) return;
  themeSlug = slug;
  const root = document.documentElement, t = THEMES[slug];
  THEME_VARS.forEach((k) => root.style.removeProperty(`--c-${k}`));
  if (t) Object.entries(t.vars).forEach(([k, v]) => root.style.setProperty(`--c-${k}`, v));
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', t ? `rgb(${t.vars.gece})` : '#6C47FF');
  document.title = t ? `${t.name} | Okut ve Oyna` : 'Okut ve Oyna | NFC Dünyası Masa Oyunları';
  applyDeco(slug);
}

// İşletme temalarında arka planı o işletmeye uygun emojilerle süsle (sadece görsel, tıklanmaz)
const DECO = {
  'chicken-rice-crush': ['🍗', '🍚', '🍛', '🐔', '🥘', '🍚', '🌶️', '🐔'],
  'durum-max': ['🌯', '🥙', '🌶️', '🌯', '🍟', '🔥', '🥙', '🌯'],
  'springfield': ['🌯', '🔥', '🥙', '🌯', '🌶️', '🍟', '🔥', '🌯'],
  'fried-chiko': ['🍗', '🐔', '🍟', '🍗', '🥤', '🐔', '🍔', '🍗'],
  'los-bravos': ['🍗', '🍔', '🍟', '🐔', '🔥', '🥤', '🍔', '🐔'],
  'eliz': ['🧇', '🍓', '🍫', '🍨', '🍌', '🧇', '🍓', '🥤'],
};
function decoUrl(list) {
  const spots = [[34, 44, -18, 46], [150, 30, 14, 40], [262, 58, -8, 50], [78, 142, 20, 52], [208, 150, -22, 44], [20, 246, 10, 42], [130, 262, -14, 54], [262, 252, 18, 46]];
  const txt = spots.map(([x, y, r, z], i) => `<text x="${x}" y="${y}" font-size="${z}" transform="rotate(${r} ${x} ${y})">${list[i % list.length]}</text>`).join('');
  return `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="320" height="320">${txt}</svg>`)}")`;
}
function decoOf(slug) { const d = THEMES[slug]?.deco; return d?.length ? d : DECO[slug]; }
function applyDeco(slug) {
  let el = document.getElementById('deco');
  const list = decoOf(slug);
  // arka planda uçuşan şekiller (parti.js) panelden eklenen temalarda da işletmenin süsleri olur
  if (list && THEMES[slug]?.deco?.length) {
    document.documentElement.setAttribute('data-th', slug);
    document.querySelectorAll('#bgfx i').forEach((n, k) => { n.textContent = list[k % list.length]; });
  }
  if (!list) { el?.remove(); return; }
  if (!el) { el = document.createElement('div'); el.id = 'deco'; el.setAttribute('aria-hidden', 'true'); document.body.prepend(el); }
  el.style.backgroundImage = decoUrl(list);
}

// ---- Yönetici panelinden gelen temalar (/api/tema/<kod>): yerleşik temayı günceller ya da yeni tema ekler ----
const STATIK = { ...THEMES };
const UZAK = new Map();
const hex2 = (rgb) => '#' + String(rgb).split(' ').map((x) => Math.max(0, Math.min(255, +x || 0)).toString(16).padStart(2, '0')).join('');
const karis = (rgb, to, k) => { const a = String(rgb).split(' ').map(Number); return '#' + a.map((x, i) => Math.round(x + (to[i] - x) * k).toString(16).padStart(2, '0')).join(''); };
function arenaOto(v) {
  const W = [255, 255, 255];
  return { fa: karis(v.gece, W, 0.55), fb: karis(v.gece, W, 0.75), rug: hex2(v.gece), rugB: hex2(v.ortu), edge: hex2(v.limon), haze: karis(v.gece, W, 0.92), top: '#58c4ff', hor: karis(v.gece, W, 0.85), K: [hex2(v.gece), hex2(v.limon), '#ffffff', hex2(v.morarti), hex2(v.cay), hex2(v.murekkep)] };
}
function uzakUygula(slug, d) {
  if (!d || d.yok) { if (STATIK[slug]) THEMES[slug] = STATIK[slug]; else delete THEMES[slug]; return; }
  if (d.aktif === false || !d.tema?.vars) { delete THEMES[slug]; return; }
  const b = STATIK[slug] || {}, t = d.tema;
  THEMES[slug] = { ...b, ...t, logo: t.logo || b.logo, shape: t.shape || undefined, links: { ...(b.links || {}), ...(t.links || {}) }, vars: { ...t.vars }, arena: b.arena || arenaOto(t.vars) };
}
function uzakTema(slug) {
  if (!SLUG_OK(slug)) return Promise.resolve();
  if (UZAK.has(slug)) return UZAK.get(slug);
  let onceki = null;
  try { onceki = JSON.parse(localStorage.getItem('oyun-uzak:' + slug) || 'null'); if (onceki) uzakUygula(slug, onceki); } catch { /* yok say */ }
  const p = fetch('/api/tema/' + slug, { cache: 'no-cache' })
    .then((r) => (r.status === 404 ? { yok: true } : r.ok ? r.json() : null))
    .then((d) => {
      if (!d || (d.yok && !onceki && !STATIK[slug] && !THEMES[slug])) return;
      if (JSON.stringify(d) === JSON.stringify(onceki)) return;
      try { if (d.yok) localStorage.removeItem('oyun-uzak:' + slug); else localStorage.setItem('oyun-uzak:' + slug, JSON.stringify(d)); } catch { /* dolu */ }
      uzakUygula(slug, d);
      themeSlug = '\u0000'; render();
    })
    .catch(() => {});
  UZAK.set(slug, p);
  return p;
}
const ilkTema = qrSlug ? uzakTema(qrSlug) : null;
let temaBekle = !!(qrSlug && !THEMES[qrSlug] && SLUG_OK(qrSlug)); // yeni tema gelene kadar varsayılan görünüm hiç çizilmesin
// İşletme temasında "Bizi puanla" ve "Bizi takip et" butonları (sadece QR ile gelenlerde)
function brandLinks() {
  const t = THEMES[themeSlug];
  if (!t?.links) return '';
  const b = 'display:inline-flex;align-items:center;gap:6px;padding:10px 16px;border-radius:9999px;font-weight:800;font-size:14px;text-decoration:none;border:3px solid rgb(var(--c-murekkep));box-shadow:3px 3px 0 rgb(var(--c-murekkep));';
  return `<div style="display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin-top:16px">
    ${t.links.review ? `<a href="${esc(t.links.review)}" target="_blank" rel="noopener" data-link="google" style="${b}background:rgb(var(--c-limon));color:rgb(var(--c-murekkep))">⭐ Bizi puanla</a>` : ''}
    ${t.links.instagram ? `<a href="https://instagram.com/${esc(t.links.instagram)}" target="_blank" rel="noopener" data-link="instagram" style="${b}background:rgb(var(--c-ortu));color:rgb(var(--c-murekkep))">📷 Bizi takip et</a>` : ''}
  </div>`;
}
// Tıklamaları işletme için say (kaç kişi puanla/takip et'e bastı)
document.addEventListener('click', (e) => {
  const a = e.target.closest?.('a[data-link]');
  if (a && themeSlug) emit('stat:link', { source: themeSlug, type: a.dataset.link });
});

function brandHero() {
  const t = THEMES[themeSlug];
  if (!t) return `<img src="${OKUT}" alt="Okut ve Oyna" width="640" height="366" class="hero-logo" style="width:min(250px,76%);height:auto;margin:0 auto">\n      <p class="mt-3 text-sm font-semibold text-ortu/50">NFC Dünyası</p>`;
  if (t.shape === 'wide') return `<img src="${t.logo}" alt="${esc(t.name)}" style="width:min(340px,90%);height:auto;margin:0 auto;filter:drop-shadow(3px 3px 0 rgb(var(--c-murekkep)))">\n      <p class="mt-3 text-sm font-semibold text-ortu/80">${esc(t.tagline)} · NFC Dünyası altyapısıyla</p>${brandLinks()}`;
  return `<img src="${t.logo}" alt="${esc(t.name)}" width="320" height="320" style="width:180px;height:180px;margin:0 auto;border-radius:9999px;border:4px solid rgb(var(--c-ortu));box-shadow:4px 4px 0 rgb(var(--c-murekkep))">
      <p class="mt-4 text-4xl font-extrabold tracking-wide">${esc(t.name)}</p><p class="mt-1 text-sm font-semibold text-ortu/70">${esc(t.tagline)} · NFC Dünyası altyapısıyla</p>${brandLinks()}`;
}

function render() {
  if (temaBekle) return;
  syncTheme();
  const next = !state.room ? 'home' : state.room.gameId ? `game:${state.room.gameId}` : 'lobby';

  if (next === 'home' || next === 'lobby') sfx.setScene('lobby');

  if (next !== currentScreen) {
    if (currentScreen?.startsWith('game:')) gameRenderers[currentScreen.slice(5)]?.destroy?.();
    currentScreen = next;
    window.scrollTo(0, 0);
    if (next === 'home') renderHome();
    else if (next === 'lobby') renderLobby();
    else renderGameShell();
  } else if (next === 'lobby') {
    renderLobby();
  } else if (next.startsWith('game:')) {
    renderGameHeader();
    updateGame();
  }
  renderTimer();
}

/* ======================= Ses düğmeleri ======================= */

const audioButtons = () => `
  <button data-act="music" aria-label="Müziği aç/kapat" class="btn shrink-0 rounded-full border-2 border-murekkep bg-morarti px-2.5 py-1.5 text-base shadow-sticker-sm ${sfx.isMusicOn() ? '' : 'opacity-50'}">🎵</button>
  <button data-act="sound" aria-label="Efektleri aç/kapat" class="btn shrink-0 rounded-full border-2 border-murekkep bg-morarti px-2.5 py-1.5 text-base shadow-sticker-sm">${sfx.isMuted() ? '🔇' : '🔊'}</button>`;

